        /// The pattern Live tail shows each log line with. Columns are wrapped in braces, such as `PID: {message_json.pid} {level} {message}`. It's null when the collector's source doesn't receive logs. See [Formatting logs](https://betterstack.com/docs/logs/using-logtail/formatting-logs/). A collector whose source doesn't receive logs refuses it.
        /// </summary>
        [Input("liveTailPattern")]
        public Input<string>? LiveTailPattern { get; set; }

        /// <summary>
        /// The pattern Live tail shows each span with. Columns are wrapped in braces, such as `{span.name} {duration}`. It's null when the collector's source doesn't receive spans. See [Formatting logs](https://betterstack.com/docs/logs/using-logtail/formatting-logs/). A collector whose source doesn't receive spans refuses it.
        /// </summary>
        [Input("liveTailPatternSpans")]
        public Input<string>? LiveTailPatternSpans { get; set; }

        /// <summary>
        /// Days logs are kept, one of the retention periods your plan offers.
        /// </summary>
        [Input("logsRetention")]
        public Input<int>? LogsRetention { get; set; }

        /// <summary>
        /// Days metrics are kept, one of the retention periods your plan offers.
        /// </summary>
        [Input("metricsRetention")]
        public Input<int>? MetricsRetention { get; set; }

        /// <summary>
        /// Collector name.
        /// </summary>
        [Input("name")]
        public Input<string>? Name { get; set; }

        /// <summary>
        /// A note about the collector. Remove the argument to clear it.
        /// </summary>
        [Input("note")]
        public Input<string>? Note { get; set; }

        /// <summary>
        /// When a host of the collector last checked in, or null when no host has checked in yet.
        /// </summary>
        [Input("pingedAt")]
        public Input<string>? PingedAt { get; set; }

        /// <summary>
        /// Where the collector runs. Can't be changed after the collector is created. Valid values: 'docker', 'swarm', 'kubernetes'.
        /// </summary>
        [Input("platform")]
        public InputUnion<string, Pulumi.BetterStack.CollectorPlatform>? Platform { get; set; }

        [Input("secret")]
        private Input<string>? _secret;

        /// <summary>
        /// Secret the deployed collector authenticates with. Returned on every read. To print it, export it as a stack output and run pulumi stack output with its name and --show-secrets.
        /// </summary>
        public Input<string>? Secret
        {
            get => _secret;
            set
            {
                var emptySecret = Output.CreateSecret(0);
                _secret = Output.Tuple<Input<string>?, int>(value, emptySecret).Apply(t => t.Item1);
            }
        }

        [Input("serviceFields")]
        private InputList<Inputs.CollectorServiceFieldGetArgs>? _serviceFields;

        /// <summary>
        /// Log fields that break data down by service. Each entry needs a `NameKey`, and `TypeKey` can be null to skip it. The list replaces the existing one, and `[]` removes them all.
        /// </summary>
        public InputList<Inputs.CollectorServiceFieldGetArgs> ServiceFields
        {
            get => _serviceFields ?? (_serviceFields = new InputList<Inputs.CollectorServiceFieldGetArgs>());
            set => _serviceFields = value;
        }

        /// <summary>
        /// Source group the collector's source belongs to, or null when it's in no group. Get the IDs via [List source groups](https://betterstack.com/docs/logs/api/list-all-existing-source-groups/).
        /// </summary>
        [Input("sourceGroupId")]
        public Input<string>? SourceGroupId { get; set; }

        /// <summary>
        /// ID of the source the collector sends data to.
        /// </summary>
        [Input("sourceId")]
        public Input<string>? SourceId { get; set; }

        /// <summary>
        /// The collector's status, worked out from its hosts, one of 'pending', 'up', 'degraded', 'unknown', 'partially_up', 'unsupported_version' or 'down'.
        /// </summary>
        [Input("status")]
        public Input<string>? Status { get; set; }

        /// <summary>
        /// Team that owns the collector, such as 't123'. Defaults to the provider's `TeamId`. Set it to create this object in another team. Changing it replaces the resource, because an object can't move to another team.
        /// </summary>
        [Input("teamId")]
        public Input<string>? TeamId { get; set; }

        /// <summary>
        /// Name of the team that owns the collector.
        /// </summary>
        [Input("teamName")]
        public Input<string>? TeamName { get; set; }

        /// <summary>
        /// When the collector was last updated.
        /// </summary>
        [Input("updatedAt")]
        public Input<string>? UpdatedAt { get; set; }

        /// <summary>
        /// Your own Vector configuration in YAML, merged into the configuration the collector runs with.
        /// </summary>
        [Input("userVectorConfig")]
        public Input<string>? UserVectorConfig { get; set; }

        public CollectorState()
        {
        }
        public static new CollectorState Empty => new CollectorState();
    }
}
